& $csc /nologo /optimize+ /platform:x64 /target:exe /reference:System.Web.Extensions.dll /reference:System.Security.dll /reference:System.Management.dll /reference:Microsoft.CSharp.dll "/reference:$mi" "/reference:$(Join-Path $env:SystemRoot "Microsoft.NET/Framework64/v4.0.30319/System.Runtime.WindowsRuntime.dll")" "/reference:$(Join-Path $env:SystemRoot "System32/WinMetadata/Windows.Foundation.winmd")" "/reference:$(Join-Path $env:SystemRoot "System32/WinMetadata/Windows.ApplicationModel.winmd")" "/reference:$(Join-Path $env:SystemRoot "System32/WinMetadata/Windows.Management.winmd")" "/reference:$(Join-Path $env:SystemRoot "System32/WinMetadata/Windows.Storage.winmd")" "/reference:$(Join-Path $env:SystemRoot "System32/WinMetadata/Windows.System.winmd")" "/reference:$(Join-Path $env:SystemRoot "Microsoft.NET/assembly/GAC_MSIL/System.Runtime/v4.0_4.0.0.0__b03f5f7f11d50a3a/System.Runtime.dll")" "/reference:$(Join-Path $env:SystemRoot "Microsoft.NET/assembly/GAC_MSIL/System.Runtime.InteropServices.WindowsRuntime/v4.0_4.0.0.0__b03f5f7f11d50a3a/System.Runtime.InteropServices.WindowsRuntime.dll")" "/out:$out" (Join-Path $PSScriptRoot 'Program.cs') (Join-Path $PSScriptRoot 'Sources.cs') (Join-Path $PSScriptRoot 'State.cs') (Join-Path $PSScriptRoot 'RegistryState.cs') (Join-Path $PSScriptRoot 'Providers.cs') (Join-Path $PSScriptRoot 'NetworkConfiguration.cs') (Join-Path $PSScriptRoot 'ApplicationFiles.cs') (Join-Path $PSScriptRoot 'PrintingShares.cs') (Join-Path $PSScriptRoot 'DesktopStartup.cs') (Join-Path $PSScriptRoot 'ShellRegistrations.cs') (Join-Path $PSScriptRoot 'Mihomo.cs') (Join-Path $PSScriptRoot 'HypervDisks.cs') (Join-Path $PSScriptRoot 'HypervSnapshots.cs') (Join-Path $PSScriptRoot 'HypervMachines.cs') (Join-Path $PSScriptRoot 'HypervSwitches.cs') (Join-Path $PSScriptRoot 'TpmMetadata.cs') (Join-Path $PSScriptRoot 'ProvisionedPackages.cs') (Join-Path $PSScriptRoot 'AppPackages.cs') (Join-Path $PSScriptRoot 'Encryption.cs') (Join-Path $PSScriptRoot 'RemoteAccess.cs') (Join-Path $PSScriptRoot 'LocalGroups.cs') (Join-Path $PSScriptRoot 'LocalAccounts.cs') (Join-Path $PSScriptRoot 'Docker.cs') (Join-Path $PSScriptRoot 'ServicingFirmware.cs') (Join-Path $PSScriptRoot 'Modules.cs') (Join-Path $PSScriptRoot '../powershell-adapter/domains/MetadataNative.cs') (Join-Path $PSScriptRoot '../powershell-adapter/domains/IdentityNative.cs')
